import fs from "node:fs";
const root="C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/";
const scratch=process.argv[2];
for (const slug of ["energy-sharing-energiegemeinschaften","virtuelles-kraftwerk"]) {
  let src = fs.readFileSync(root+"content/ratgeber/"+slug+".js","utf8");
  src = src.replace(/"@\/lib\/([^"]+)"/g, (m,p)=>JSON.stringify("file:///"+root+"lib/"+p+".js"));
  const tmp = scratch+"/_tmp_"+slug+".mjs";
  fs.writeFileSync(tmp, src);
  const a = (await import("file:///"+tmp)).default;
  const texte=[]; const kl=s=>s.replace(/\*\*/g,"").replace(/\[([^\]]+)\]\([^)]+\)/g,"$1");
  const sm=x=>{ if(typeof x==="string") texte.push(kl(x)); else if(Array.isArray(x)) x.forEach(sm); else if(x&&typeof x==="object") Object.values(x).forEach(sm);};
  sm(a.kurzFazit); sm(a.abschnitte); sm(a.faq);
  const w=texte.join(" ").split(/\s+/).filter(Boolean).length;
  console.log(slug, w, "Wörter", Math.round(w/200),"Min", "title",a.title.length,"seo",a.seoTitle.length,"desc",a.description.length);
  console.log(a.kurzFazit.join("\n"));
  const links = JSON.stringify(a.abschnitte).match(/\]\((\/[^)]+)\)/g)||[]; console.log("interne Links:", links.length);
}
