import fs from "node:fs";
const root = "C:/Users/SALEADMIN/Downloads/Oekoinvest-Web/src/";
const scratch = "C:/Users/SALEAD~1/AppData/Local/Temp/claude/c--Users-SALEADMIN-Downloads-Oekovolt-Web-DE-Oekovolt-Web-DE/6ac8640b-bab4-4de9-9c07-3a24f91b0e42/scratchpad";
const lex = fs.readFileSync(root + "data/lexikon.js", "utf8");
for (const slug of process.argv.slice(2)) {
  let src = fs.readFileSync(root + "content/ratgeber/" + slug + ".js", "utf8");
  src = src.replace(/"@\/lib\/([^"]+)"/g, (m, p) => JSON.stringify("file:///" + root + "lib/" + p + ".js"));
  const tmp = scratch + "/_tmp_agri_" + slug + ".mjs";
  fs.writeFileSync(tmp, src);
  const a = (await import("file:///" + tmp + "?" + Date.now())).default;
  const texte = [];
  const kl = (s) => s.replace(/\*\*/g, "").replace(/\[([^\]]+)\]\([^)]+\)/g, "$1");
  const sm = (x, k) => { if (["id", "typ", "variant", "href", "url"].includes(k)) return; if (typeof x === "string") texte.push(kl(x)); else if (Array.isArray(x)) x.forEach((y) => sm(y)); else if (x && typeof x === "object") Object.entries(x).forEach(([kk, v]) => sm(v, kk)); };
  sm(a.kurzFazit); sm(a.abschnitte); sm(a.faq);
  const w = texte.join(" ").split(/\s+/).filter(Boolean).length;
  console.log(slug, w, "Wörter", Math.round(w / 200), "Min | title", a.title.length, "seo", a.seoTitle.length, "desc", a.description.length, "kf", a.kurzFazit.length, "faq", a.faq.length, "quellen", a.quellen.length);
  const alle = JSON.stringify([a.kurzFazit, a.abschnitte, a.faq]);
  const links = alle.match(/\]\((\/[^)]+)\)/g) || [];
  console.log("interne Links:", links.length, [...new Set(links)].join(" "));
  for (const l of links) { const m = l.match(/#([a-z0-9-]+)/); if (m && !lex.includes(`"${m[1]}"`)) console.log("  !! Lexikon-ID fehlt:", m[1]); }
  const tab = a.abschnitte.flatMap((s) => s.bloecke).filter((b) => b.typ === "tabelle").length;
  console.log("Tabellen:", tab);
  if (/NaN|undefined|–\s*€/.test(alle)) console.log("  !! NaN/undefined im Text");
}

