import { chromium } from "playwright";
const b = await chromium.launch();
for (const slug of process.argv.slice(2)) {
  for (const breite of [1440, 390]) {
    const p = await b.newPage({ viewport: { width: breite, height: breite < 600 ? 844 : 900 } });
    const fehler = [];
    p.on("pageerror", (e) => fehler.push("PAGEERROR " + e.message));
    p.on("console", (m) => m.type() === "error" && fehler.push("CONSOLE " + m.text().slice(0, 200)));
    const r = await p.goto("http://localhost:3100/ratgeber/" + slug, { waitUntil: "load", timeout: 240000 });
    await p.waitForTimeout(2500);
    try { await p.getByRole("button", { name: "Nur notwendige" }).click({ timeout: 1500 }); } catch {}
    await p.evaluate(() => document.querySelectorAll(".ov-reveal").forEach((e) => e.classList.add("is-visible")));
    const info = await p.evaluate(() => {
      const w = document.documentElement.clientWidth;
      const bad = [...document.querySelectorAll("main *")].filter((e) => { const x = e.getBoundingClientRect(); return x.right > w + 1 && !e.closest(".overflow-x-auto, [class*='overflow-x']"); }).slice(0, 6).map((e) => e.tagName + "." + (e.className?.toString?.() || "").slice(0, 50));
      return { scrollW: document.documentElement.scrollWidth, w, bad, lesezeit: (document.body.innerText.match(/\d+ Min\. Lesezeit/) || [])[0], tabellen: document.querySelectorAll("main table").length, h1: document.querySelector("h1")?.innerText };
    });
    console.log(r.status(), slug, breite, JSON.stringify(info), fehler.length ? "\n  " + fehler.join("\n  ") : "");
    await p.screenshot({ path: `shots/${slug}_${breite}_top.png` });
    const tabs = await p.$$("main table");
    for (let i = 0; i < Math.min(tabs.length, 3); i++) {
      await tabs[i].scrollIntoViewIfNeeded();
      await p.waitForTimeout(300);
      await p.screenshot({ path: `shots/${slug}_${breite}_tab${i}.png` });
    }
    await p.close();
  }
}
await b.close();

